mapper.select:

SELECT
  count(*) totcnt
FROM
  ttokssaemdb.member member,
  ttokssaemdb.vocaexam vocaexam

  AND member.memberid = vocaexam.memberid

    AND member.branchid = #{branchid}


    AND vocaexam.memodate = #{memodate}


    AND (
      member.membername LIKE #{likeQuery}
    )

SELECT R1.* FROM( SELECT member.memberid, member.membername, vocaexam.examid, vocaexam.memodate, vocaexam.vocalevel, (SELECT codename FROM cmm_code WHERE code = vocaexam.vocalevel AND codetype = 'VOCALEVEL') vocalevel_name, vocaexam.vocano, vocaexam.targetcount, vocaexam.degree, vocaexam.result, vocaexam.total, vocaexam.wrong, DATE_FORMAT(vocaexam.startdate, '%Y-%m-%d %H:%i:%s') startdate, DATE_FORMAT(vocaexam.findate, '%Y-%m-%d %H:%i:%s') findate FROM ttokssaemdb.member member, ttokssaemdb.vocaexam vocaexam
AND member.memberid = vocaexam.memberid
AND member.branchid = #{branchid}
AND vocaexam.memodate = #{memodate}
AND ( member.membername LIKE #{likeQuery} )
vocaexam.examid vocaexam.vocalevel vocaexam.vocalevel vocaexam.vocano vocaexam.memodate vocaexam.result member.membername DESC ASC DESC
) R1
LIMIT ${length} OFFSET ${start}
